import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // restrict to admissible domain for adjustMtFeeRate
        vm.assume(mtFeeRate <= 10**18);

        // drive c through adjustMtFeeRate
        c.adjustMtFeeRate(mtFeeRate);

        // after adjustMtFeeRate, read public state
        (,, uint256 B0, uint256 Q0,,, uint256 R) = c.getPMMStateForCall();
        uint256 baseReserve;
        uint256 quoteReserve;
        (baseReserve, quoteReserve) = c.getVaultReserve();

        // the property: if RState is ONE, then both targets must equal the actual reserves
        // the bug leaves _BASE_TARGET_ stale when transitioning from BELOW_ONE to ONE in correctRState
        if (R == 1) {
            assertTrue(B0 == baseReserve && Q0 == quoteReserve);
        } else {
            // when not in state ONE, nothing is asserted; property vacuously holds
            assertTrue(true);
        }
    }
}

