pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 mtFeeRate, uint256 fakeBaseReserve, uint256 fakeQuoteReserve) public {
        // Admissible domain: mtFeeRate <= 1e18 as required by adjustMtFeeRate; fake reserves within uint112 range.
        vm.assume(mtFeeRate <= 1e18);
        vm.assume(fakeBaseReserve <= type(uint112).max);
        vm.assume(fakeQuoteReserve <= type(uint112).max);
        // To reach the bug we need the initial PMM state in BELOW_ONE with _BASE_RESERVE_ < _BASE_TARGET_.
        // We directly manipulate storage to set up that state, because C has no public init for these.
        // State layout: we follow GSPStorage order.
        // 0: _GSP_INITIALIZED_, 1: _IS_OPEN_TWAP_, 2: _MAINTAINER_, 3: _BASE_TOKEN_, 4: _QUOTE_TOKEN_,
        // 5: _BASE_RESERVE_, 6: _QUOTE_RESERVE_, 7: _BLOCK_TIMESTAMP_LAST_, 8: _BASE_PRICE_CUMULATIVE_LAST_,
        // 9: _BASE_TARGET_, 10: _QUOTE_TARGET_, 11: _RState_, ...
        bytes32 baseReserveSlot = bytes32(uint256(5));
        bytes32 quoteReserveSlot = bytes32(uint256(6));
        bytes32 baseTargetSlot = bytes32(uint256(9));
        bytes32 quoteTargetSlot = bytes32(uint256(10));
        bytes32 rStateSlot = bytes32(uint256(11));

        // We need BASE_RESERVE < BASE_TARGET, so set BASE_TARGET higher.
        uint112 baseTarget = uint112(fakeBaseReserve + 1e12 + (fakeBaseReserve % 1e12));
        // Set RState to BELOW_ONE (1)
        vm.store(address(c), rStateSlot, bytes32(uint256(1)));
        vm.store(address(c), baseReserveSlot, bytes32(uint256(fakeBaseReserve)));
        vm.store(address(c), quoteReserveSlot, bytes32(uint256(fakeQuoteReserve)));
        vm.store(address(c), baseTargetSlot, bytes32(uint256(baseTarget)));
        vm.store(address(c), quoteTargetSlot, bytes32(uint256(fakeQuoteReserve))); // target == reserve for quote

        // Call adjustMtFeeRate, which will trigger correctRState internally? No, adjustMtFeeRate does NOT call correctRState.
        // We need to call correctRState explicitly.
        // Since correctRState is public, we can call it.
        // The bug triggers when correctRState is called while BELOW_ONE and BASE_RESERVE < BASE_TARGET.
        // After that, RState should be ONE and targets should equal reserves.

        c.adjustMtFeeRate(mtFeeRate);
        // Now call correctRState
        c.correctRState();

        // After correctRState, if RState is ONE, then BASE_TARGET must equal BASE_RESERVE.
        // We read the state through getter of getPMMStateForCall which returns all fields.
        (, , uint256 B, uint256 Q, uint256 B0, uint256 Q0, uint256 R) = c.getPMMStateForCall();

        // Rule: if R is ONE (0), then B0 == B and Q0 == Q.
        if (R == 0) {
            assertTrue(B0 == B && Q0 == Q);
        } else {
            // If not ONE, the test is vacuously true for this input; we just pass.
            assertTrue(true);
        }
    }
}

