pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // Restrict mtFeeRate to the admissible domain (<= 1e18)
        vm.assume(mtFeeRate <= 1e18);
        // make the call as MAINTAINER (deployer)
        vm.prank(address(this));
        c.adjustMtFeeRate(mtFeeRate);
        // After the call, if RState_ is ONE, BASE_TARGET_ must equal BASE_RESERVE_
        uint32 rState = c._RState_();
        if (rState == uint32(1)) { // RState.ONE
            assertTrue(c._BASE_TARGET_() == c._BASE_RESERVE_());
        } else {
            // Outside ONE, the invariant is not required, so the test passes vacuously
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 i, uint256 k, uint256 b, uint256 q, uint256 b0, uint256 q0, uint256 rState) public {
        require(rState == uint256(PMMPricing.RState.ABOVE_ONE));
        require(q0 > q);
        require(b0 >= b);

        c.adjustPrice(i);
        c.adjustMtFeeRate(k);
        c.sync();
        c.correctRState();

        ( , , uint256 baseReserve, , , , ) = c.getPMMStateForCall();
        uint256 baseTarget = c._BASE_TARGET_();

        assert(baseTarget >= baseReserve);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 baseInput, uint256 quoteInput) public payable {
        require(true);
        uint256 oldBaseTarget = c._BASE_TARGET_();
        uint256 oldTotalSupply = c.totalSupply();
        c.buyShares(to);
        uint256 newBaseTarget = c._BASE_TARGET_();
        uint256 newTotalSupply = c.totalSupply();
        assert(oldTotalSupply == 0 || newBaseTarget == oldBaseTarget + (oldBaseTarget * (newTotalSupply - oldTotalSupply) / oldTotalSupply));
    }
}
